28","name":"exc_refi_m15_offer","dest":"c"}},"entry":{"default":{"path":"B","step":"NEW"},"quizDone":{"path":"D","step":"QUIZ"}},"sequences":{"B":[{"code":"M1","next":{"minutes":5}},{"code":"M2","next":{"hours":3},"thenPath":"C"}],"C":[{"code":"M3","next":{"days":1,"at":"10:00"}},{"code":"M4","next":{"days":2,"at":"10:00"}},{"code":"M5","next":{"days":4,"at":"10:00"}},{"code":"M6","next":{"days":14},"thenPath":"L"}],"D":[{"code":"M7","next":{"days":1}},{"code":"M8","next":{"days":2}},{"code":"M9","next":{"days":14},"thenPath":"L"}],"G":[{"code":"M12","next":{"days":3}},{"code":"M13","next":{"days":5}},{"code":"M14","next":{"days":11}},{"code":"M15","next":{"days":14},"thenPath":"L"}],"L":[]},"quizUpgrade":{"fromPaths":["B","C"],"to":{"path":"D","step":"QUIZ"}},"meeting":{"booked":"M10","reminder":"M10R","noShow":"M11","after":{"path":"G","step":"MET","next":{"days":2,"at":"10:00"}},"noShowLimit":2,"holdPath":"L"},"rules":{"onePerDayPaths":["C","D","G"],"sameDayAllowed":["M2","M3","M7"],"holdDays":14},"links":{"q":"https://refi.excelentfinance.com/?utm_source=whatsapp&utm_medium=funnel&utm_campaign=refi_funnel#check","c":"https://calendly.com/excellnet/15min","g":"https://share.google/L6zPPGazOqwdvB1pH","m":"https://www.midrag.co.il/SpCard/Sp/94658","b":"https://www.bizreviews.co.il/provider/peled-yoram"},"linkByStep":{"M2":"q","M3":"b","M4":"c","M5":"q","M7":"c","M8":"c","M9":"c","R1":"c","R2":"c","M10":"c","M11":"c","M12":"g","M13":"m","M15":"c"},"handoff":{"heatAtLeast":70,"onReply":true,"onBooking":true},"kpiTargets":{"costPerPayingClient":1400,"costPerMeeting":350},"meta":{"campaignIds":["120252891592490603"],"adAccount":"287081049104797"},"groups":{"meetings":"group_mm883gr6"},"identity":{"profile":"excelent_finance","nameInMessages":"יורם פלד","contactPhone":"excelent_contact","testPhones":["excelent_contact","backup"],"approved":true,"approvedBy":"יורם","approvedAt":"2026-10-20","source":"הנחיות יורם בשיחה מ 20.10.2026"}};
const BIZ = {
  "_doc": "פרטי העסק הקבועים: מספרים, שמות ופרופילים עסקיים. כל קמפיין בוחר פרופיל ופרטי קשר במפורש בקובץ שלו. שינוי כאן רק לפי הנחיה מפורשת של יורם.",
