    "yoram_050":        {"number": "050-2234052", "e164": "972502234052", "role": "מספר של יורם: ניסויים ובדיקות קמפיינים, גיבויים ושימושים תפעוליים, פעילות נדל״ן בנגב המערבי כשהוגדר במפורש לקמפיין, ושימוש אישי. משמש כמספר קשר רק בקמפיין שהגדיר אותו במפורש."}
  },
  "profiles": {
    "excelent_finance": {
      "label": "אקסלנט משכנתאות ופיננסים",
      "brand": "אקסלנט יועצי משכנתאות ופיננסים",
      "nameInMessages": "יורם פלד",
      "allowedNames": ["יורם", "יורם פלד", "יורם אקסלנט"],
      "allowedContactPhones": ["excelent_contact"],
      "allowedTestPhones": ["excelent_contact", "backup", "yoram_050"]
    },
